<script setup lang="ts">
import {t} from "../i18n"
import {ref,computed,watch}from'vue'
import{useQuasar}from'quasar'
import{api,send}from'../api'
import type{Media}from'../types'
import Icon from'./Icon.vue'
import ImageEditor from'./ImageEditor.vue'
const props=withDefaults(defineProps<{siteId:number;picker?:boolean}>(),{picker:false}),emit=defineEmits(['select']),q=useQuasar()
const media=ref<Media[]>([]),folders=ref<any[]>([]),search=ref(''),folder=ref<number|string>('all'),kind=ref('All types'),sort=ref('Newest first'),uploading=ref(false),progress=ref(0),fileInput=ref<HTMLInputElement>(),edit=ref<Media|null>(null),detail=ref(false),imageEdit=ref(false),drag=ref(false),folderDialog=ref(false),folderForm=ref<any>({name:'',parent_id:null}),loading=ref(false)
const filtered=computed(()=>{let list=media.value.filter(m=>(folder.value==='all'||(folder.value===0?!m.folder_id:m.folder_id===folder.value))&&(m.name+' '+m.alt).toLowerCase().includes(search.value.toLowerCase())&&(kind.value==='All types'||(kind.value==='Images'?m.mime.startsWith('image/'):kind.value==='Videos'?m.mime.startsWith('video/'):!m.mime.startsWith('image/')&&!m.mime.startsWith('video/'))));return [...list].sort((a,b)=>sort.value==='Name A–Z'?a.name.localeCompare(b.name):sort.value==='Largest first'?b.size-a.size:Date.parse(b.created_at)-Date.parse(a.created_at))})
function folderName(id:number,seen:number[]=[]):string{const f=folders.value.find(f=>f.id===id);if(!f||seen.includes(id))return '';return(f.parent_id?folderName(f.parent_id,[...seen,id])+' / ':'')+f.name}
const folderOptions=computed(()=>[{label:'Unfiled',value:null},...folders.value.map(f=>({label:folderName(f.id),value:f.id}))])
async function load(){loading.value=true;try{const [m,f]=await Promise.all([api('/websites/'+props.siteId+'/media'),api('/websites/'+props.siteId+'/media-folders')]);media.value=m;folders.value=f}catch(e:any){q.notify({type:'negative',message:t(e.message)})}finally{loading.value=false}}
watch(()=>props.siteId,()=>{folder.value='all';load()},{immediate:true})
async function upload(files:FileList|null){if(!files?.length)return;uploading.value=true;progress.value=0;const data=new FormData();Array.from(files).forEach(f=>data.append('files[]',f));try{const {token}=await api('/csrf');const uploaded:Media[]=await new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST','/api/websites/'+props.siteId+'/media');xhr.withCredentials=true;xhr.setRequestHeader('Accept','application/json');xhr.setRequestHeader('X-CSRF-TOKEN',token);xhr.upload.onprogress=e=>{if(e.lengthComputable)progress.value=e.loaded/e.total};xhr.onerror=()=>reject(new Error('Upload failed. Check your connection.'));xhr.onload=()=>{let result;try{result=JSON.parse(xhr.responseText)}catch{return reject(new Error('Upload failed. Check the server upload-size limit.'))}if(xhr.status>=200&&xhr.status<300)resolve(result);else reject(new Error(result.message||'Upload failed.'))};xhr.send(data)});if(typeof folder.value==='number'&&folder.value>0)for(const m of uploaded)await api('/websites/'+props.siteId+'/media/'+m.id,send('PUT',{...m,folder_id:folder.value}));await load();q.notify({type:'positive',message:t('Your media is ready to use.')})}catch(e:any){q.notify({type:'negative',message:t(e.message)})}finally{uploading.value=false;if(fileInput.value)fileInput.value.value=''}}
function open(m:Media){if(props.picker){if(!m.mime.startsWith('image/'))return q.notify({type:'warning',message:t('Choose an image for this block.')});emit('select',m)}else{edit.value={...m,folder_id:m.folder_id||null};detail.value=true}}
async function save(){if(!edit.value)return;try{await api('/websites/'+props.siteId+'/media/'+edit.value.id,send('PUT',edit.value));await load();detail.value=false;q.notify({type:'positive',message:t('Media details saved.')})}catch(e:any){q.notify({type:'negative',message:t(e.message)})}}
function remove(){q.dialog({title:t('Delete this media?'),message:t('Pages using this file may display a missing image. This cannot be undone.'),cancel:true,persistent:true}).onOk(async()=>{try{await api('/websites/'+props.siteId+'/media/'+edit.value?.id,{method:'DELETE'});detail.value=false;await load()}catch(e:any){q.notify({type:'negative',message:t(e.message)})}})}
function editFolder(id?:number){folderForm.value=id?{...folders.value.find(f=>f.id===id)}:{name:'',parent_id:typeof folder.value==='number'&&folder.value>0?folder.value:null};folderDialog.value=true}
async function saveFolder(){try{const f=folderForm.value;await api('/websites/'+props.siteId+'/media-folders'+(f.id?'/'+f.id:''),send(f.id?'PUT':'POST',f));folderDialog.value=false;await load()}catch(e:any){q.notify({type:'negative',message:t(e.message)})}}
function deleteFolder(){q.dialog({title:t('Delete folder?'),message:t('Only empty folders can be deleted. Move their files and subfolders first.'),cancel:true}).onOk(async()=>{try{await api('/websites/'+props.siteId+'/media-folders/'+folder.value,{method:'DELETE'});folder.value='all';await load()}catch(e:any){q.notify({type:'negative',message:t(e.message)})}})}
</script>
<template><div class="media-library"><div class="website-toolbar"><div class="inline-search"><Icon name="Search" :size="17"/><input v-model="search" :placeholder="$t('Search your media…')" :aria-label="$t('Search media')"></div><q-select dense outlined v-model="folder" :options="[{label:$t('All folders'),value:'all'},...folderOptions.map(f=>({...f,value:f.value||0}))]" emit-value map-options style="min-width:170px"/><button class="btn secondary" @click="editFolder()"><Icon name="Plus" :size="15"/>{{ $t("Folder") }}</button><q-btn v-if="typeof folder==='number' && folder>0" flat round dense :aria-label="$t('Folder actions')"><Icon name="Ellipsis"/><q-menu><q-list><q-item clickable v-close-popup @click="editFolder(Number(folder))"><q-item-section>{{ $t("Rename / move folder") }}</q-item-section></q-item><q-item clickable v-close-popup @click="deleteFolder"><q-item-section>{{ $t("Delete empty folder") }}</q-item-section></q-item></q-list></q-menu></q-btn><q-btn unelevated color="primary" :loading="uploading" @click="fileInput?.click()"><Icon name="Upload" :size="16"/>&nbsp; {{ $t("Upload files") }}</q-btn><input hidden type="file" multiple ref="fileInput" accept=".jpg,.jpeg,.png,.webp,.gif,.mp4,.pdf,.doc,.docx,.xls,.xlsx" @change="upload(($event.target as HTMLInputElement).files)"></div><div :class="['upload-zone',{drag}]" @dragover.prevent="drag=true" @dragleave.prevent="drag=false" @drop.prevent="drag=false;upload($event.dataTransfer?.files||null)" @click="fileInput?.click()"><Icon name="CloudUpload" :size="30"/><strong>{{ $t("Drop a little inspiration here") }}</strong><p>{{ $t("Drag & drop files, or") }} <span>{{ $t("browse your computer") }}</span></p><small>{{ $t("Images, video, PDF, and Office documents · Up to 20 MB per file") }}</small><q-linear-progress v-if="uploading" :value="progress" color="primary" class="upload-progress"/></div><div class="website-toolbar media-filters"><span class="media-count">{{ filtered.length }} {{ $t("assets") }}</span><q-select emit-value map-options outlined dense v-model="kind" :options="$translatedOptions(['All types','Images','Videos','Documents'])"/><q-select emit-value map-options outlined dense v-model="sort" :options="$translatedOptions(['Newest first','Name A–Z','Largest first'])"/></div><q-linear-progress v-if="loading" indeterminate color="primary"/><div class="media-grid"><button v-for="m in filtered" :key="m.id" class="media-item" @click="open(m)"><img v-if="m.mime.startsWith('image/')" :src="m.url" :alt="m.alt" loading="lazy"><div v-else class="file-thumbnail"><Icon :name="m.mime.includes('video')?'Film':'FileText'" :size="40"/></div><div><strong>{{ m.name }}</strong><small>{{ m.mime.split('/')[1]?.toUpperCase() }} · {{ Math.round(m.size/1024) }} {{ $t("KB") }} <span v-if="m.width">· {{ m.width }} × {{ m.height }}</span></small></div></button></div><p v-if="!filtered.length&&!loading" class="empty-text">{{ $t("No assets found. Upload a file or choose another filter.") }}</p></div><q-dialog v-model="detail"><q-card class="standard-dialog" v-if="edit"><img v-if="edit.mime.startsWith('image/')" :src="edit.url" class="media-detail-image"><button v-if="['image/jpeg','image/png','image/webp'].includes(edit.mime)" class="btn secondary" @click="imageEdit=true"><Icon name="SlidersHorizontal" :size="16"/>{{ $t("Crop, resize & optimize") }}</button><h2 class="media-detail-title">{{ $t("Make every detail count.") }}</h2><q-input outlined v-model="edit.name" :label="$t('File name')"/><q-input outlined v-model="edit.alt" :label="$t('Alternative text')" hint="Describe the image for screen readers and search engines."/><q-input outlined v-model="edit.caption" :label="$t('Caption')"/><q-input outlined v-model="edit.description" :label="$t('Description')" type="textarea" rows="2"/><q-select outlined v-model="edit.folder_id" :label="$t('Folder')" :options="folderOptions" emit-value map-options/><div class="dialog-footer"><button class="btn danger" @click="remove">{{ $t("Delete file") }}</button><button class="btn primary" @click="save">{{ $t("Save details") }}</button></div></q-card></q-dialog><q-dialog v-model="imageEdit" persistent><ImageEditor v-if="edit" :media="edit" :site-id="siteId" @close="imageEdit=false" @saved="(m:Media)=>{imageEdit=false;edit=m;load()}"/></q-dialog><q-dialog v-model="folderDialog"><q-card class="standard-dialog"><h2>{{ $t(folderForm.id?'Organize this folder.':'A home for your assets.') }}</h2><form @submit.prevent="saveFolder"><q-input outlined v-model="folderForm.name" :label="$t('Folder name')" required maxlength="100"/><q-select outlined v-model="folderForm.parent_id" :options="[{label:$t('Top level'),value:null},...folderOptions.filter(f=>f.value && f.value!==folderForm.id)]" emit-value map-options :label="$t('Parent folder')"/><div class="dialog-footer"><button class="btn secondary" type="button" @click="folderDialog=false">{{ $t("Cancel") }}</button><q-btn type="submit" color="primary" unelevated :label="$t('Save folder')"/></div></form></q-card></q-dialog></template>
